style.css:
@-moz-document domain("pinterest.com") {
/* 1. HIJACK THE CORE ENGINE */
    :root {
        /* Neapolitan Palette */
        --nea-vanilla: #FDF5E6 !important;  /* Custard */
        --nea-strawberry: #FFB7C5 !important; /* Pink */
        --nea-choc: #5D4037 !important;       /* Brown */
        --nea-vanilla-dark: #F5E6CC !important;

        /* PINTEREST VARIABLE HIJACK */
        --g-colorRed00: var(--nea-strawberry) !important;
        --g-colorRed100: var(--nea-strawberry) !important;
        --g-colorGray0: var(--nea-vanilla) !important;
        --g-colorGray100: var(--nea-vanilla-dark) !important;
        --g-colorGray200: var(--nea-choc) !important;
        --g-colorGray300: var(--nea-choc) !important;
        --g-colorGray400: var(--nea-choc) !important;
        
        /* Background & Surface Variables */
        --color-background-canvas: var(--nea-vanilla) !important;
        --color-background-container-primary: var(--nea-vanilla) !important;
        --color-background-container-secondary: var(--nea-vanilla-dark) !important;
        --color-background-main: var(--nea-vanilla) !important;
        --color-background-card-primary: var(--nea-vanilla) !important;
        --color-background-modal-primary: var(--nea-vanilla) !important;
        
        /* Text Variables */
        --color-text-primary: var(--nea-choc) !important;
        --color-text-secondary: var(--nea-choc) !important;
        --color-text-icon-primary: var(--nea-choc) !important;
    }

    /* 2. THE FONT (Ensure 'Dunkin' is installed on your PC) */
    * {
        font-family: 'Dunkin', 'Quicksand', 'Segoe UI', sans-serif !important;
        -webkit-font-smoothing: antialiased;
    }

    /* 3. AGGRESSIVE BACKGROUND CLEANUP */
    html, body, #__PWS_ROOT__, [data-test-id="full-grid-container"], 
    [role="main"], [role="navigation"], header, .FullPageModal__scroller {
        background-color: var(--nea-vanilla) !important;
    }

    /* 4. PIN CARDS & IMAGES (The Treat Box Look) */
    [data-test-id="pin"] {
        background-color: var(--nea-vanilla) !important;
        border: 3px solid var(--nea-choc) !important;
        border-radius: 28px !important;
        padding: 6px !important;
        box-shadow: 6px 6px 0px var(--nea-strawberry) !important; /* Neapolitan shadow */
    }

    [data-test-id="pin-visual-wrapper"] {
        border-radius: 20px !important;
        overflow: hidden !important;
        border: 1px solid var(--nea-choc) !important;
    }

    /* 5. HEADER & SEARCH BAR */
    [data-test-id="header-background"] {
        background-color: var(--nea-vanilla) !important;
        border-bottom: 6px solid var(--nea-strawberry) !important;
    }

    [data-test-id="search-box-input"] {
        background-color: var(--nea-vanilla-dark) !important;
        border: 3px solid var(--nea-choc) !important;
        border-radius: 12px !important;
    }

    /* 6. BUTTONS (Strawberry & Chocolate) */
    [role="button"], button, [data-test-id="save-button"] {
        background-color: var(--nea-strawberry) !important;
        border: 2px solid var(--nea-choc) !important;
        color: var(--nea-choc) !important;
        font-weight: bold !important;
        box-shadow: 2px 2px 0px var(--nea-choc) !important;
    }

    button:hover {
        transform: scale(1.05) !important;
        background-color: var(--nea-vanilla) !important;
    }

    /* 7. ICONS & NAV (Force Chocolate) */
    svg {
        fill: var(--nea-choc) !important;
        stroke: var(--nea-choc) !important;
    }

    /* 8. FLOATING MASCOT (Fixed Position) */
    body::after {
        content: "";
        position: fixed;
        bottom: 20px;
        right: 20px;
        width: 110px;
        height: 110px;
        background-image: url('https://i.imgur.com/vH7j3iO.png'); 
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 999999;
        pointer-events: none;
        filter: drop-shadow(3px 3px 0px var(--nea-choc));
    }

    /* 9. SCROLLBAR (Full Neapolitan) */
    ::-webkit-scrollbar { width: 14px; }
    ::-webkit-scrollbar-track { background: var(--nea-choc); }
    ::-webkit-scrollbar-thumb { 
        background: var(--nea-strawberry); 
        border-radius: 10px;
        border: 3px solid var(--nea-choc);
    }
    ::-webkit-scrollbar-thumb:hover { background: var(--nea-vanilla); }

    /* 10. FIX FOR MODALS & OVERLAYS */
    div[role="dialog"], div[class*="Modal"] {
        background-color: var(--nea-vanilla) !important;
        border: 4px solid var(--nea-choc) !important;
        border-radius: 30px !important;
    }
}
